message:
Running command: cat > /tmp/pltest/test_readcfg.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LINESIZE 256

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;
    char *thisline = malloc(LINESIZE);
    int linesize = LINESIZE;
    int readbytes = 0;
    int missing_lf = -1;
    int linenum = 0;

    while (fgets(thisline + readbytes, linesize - readbytes, f) != NULL) {
        char *line = thisline;
        linenum++;
        char *end = line + strlen(line);
        if (end-line == linesize-1 && *(end-1) != '\n') {
            int newlinesize = linesize * 2;
            char *newline = realloc(thisline, newlinesize);
            readbytes = linesize - 1;
            linesize = newlinesize;
            thisline = newline;
            continue;
        }
        readbytes = 0;
        if (*(end-1) == '\n') {
            *(end-1) = 0;
        } else {
            missing_lf = end - line;
        }
        printf("line %d: strlen=%ld\n", linenum, (long)(end-line));
    }
    free(thisline);
    fclose(f);
    return 0;
}
EOF
cd /tmp/pltest && gcc -g -fsanitize=address -o test_readcfg test_readcfg.c && echo "BUILD OK"
# Create a test file starting with \0
printf '\x00AAAA\n' > /tmp/pltest/input1.bin
./test_readcfg /tmp/pltest/input1.bin

